const count = 0;
count || 10;  // 10 — 0 is falsy
count ?? 10;  // 0 — only null/undefined trigger ??

const cached = "";
cached || "default";  // "default"
cached ?? "default";  // "" — empty string kept

const ttl = response?.data?.meta?.ttlSeconds;
response?.markStale?.(); // no throw if response or markStale missing

// Parsed as (a ?? b) || c — not a ?? (b || c)
const a = null, b = 0, c = 1;
(a ?? b) || c; // 1

// Dangerous auth default — wrong operator
const role = userRole || "admin"; // "" becomes admin
const safeRole = userRole ?? "guest"; // only null/undefined

// Mix ?? with ?: — always parenthesize
const label = (status ?? "unknown") === "ok" ? "Ready" : "Wait";

function process(user) {
  if (user && user.isActive && user.token) {
    return decode(user.token);
  }
  return null;
}

// typeof is safe for undeclared globals only
typeof undeclaredGlobal; // "undefined"

// + coercion
"5" + 1;  // "51" string concat
"5" - 1;  // 4 numeric subtraction
